import { loadFont as loadExo } from "@remotion/google-fonts/Exo2";
import { loadFont as loadOrb } from "@remotion/google-fonts/Orbitron";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ZONE PLAY (Zone Digital) — anúncio de 29 s: "chega de pagar caro em streaming", tudo em um só lugar por R$ 30/mês.
// Tom do logo e do Instagram: preto, amarelo-limão → verde, "Z" 3D, fonte tech larga, hexágonos e linhas neon.
// Pedido: quando a fala cita streaming, aparecem Netflix, HBO, Paramount… — entram como nomes escritos em
// cartões de assinatura (não os logos oficiais), só na parte do problema.
// Neon presente mas contido e textos centralizados com margem.
// Locução "o locutor" sem pausas e a 1,12× (audio/zoneplay-vo.wav), entra em 0,15 s. Sem áudio aqui.

const { fontFamily: ORB } = loadOrb("normal", { weights: ["700", "900"], subsets: ["latin"] });
const { fontFamily: EXO } = loadExo("normal", { weights: ["600", "800", "900"], subsets: ["latin", "latin-ext"] });

export const ZP_FPS = 30;
const VO = 0.15;
export const ZP_FRAMES = 29 * ZP_FPS;
const BG = "#050505";
const LIME = "#C6FF1A";
const GREEN = "#59D600";
const WHITE = "#FFFFFF";
const PANEL = "#121212";
const EDGE = "#2E2E2E";
const RED = "#FF3B3B";
const WA = "#25D366";
const asset = (f: string) => staticFile(`zoneplay/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.6));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO;
const bump = (t: number, at: number, amt = 0.06, d = 0.4) => (t >= at ? amt * (1 - k(t, at, d)) : 0);
// neon um pouco abaixo do cheio: cor opaca, raio contido
const glow = (c: string, s = 1) => `0 0 ${(6 * s).toFixed(1)}px ${c}, 0 0 ${(22 * s).toFixed(1)}px ${c}`;
const shakeOf = (t: number, at: number, amp = 10, d = 0.35): [number, number] => (t > at && t < at + d ? [Math.sin(t * 83) * amp * (1 - (t - at) / d), Math.cos(t * 71) * amp * (1 - (t - at) / d)] : [0, 0]);

// ───────── fundo: preto com colmeia verde, linhas neon em diagonal e partículas ─────────
const Back: React.FC<{ t: number; rays?: number; tint?: string }> = ({ t, rays = 0, tint = "89,214,0" }) => (
  <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
    <svg width={1400} height={2300} style={{ position: "absolute", left: -160, top: -190 + ((t * 40) % 156), opacity: 0.5 }}>
      <defs>
        <pattern id="zphex" width={90} height={156} patternUnits="userSpaceOnUse">
          <path d="M45 0 L90 26 L90 78 L45 104 L0 78 L0 26 Z M45 104 L45 156 M0 78 L0 130 M90 78 L90 130" fill="none" stroke={`rgba(${tint},0.16)`} strokeWidth={2} />
        </pattern>
      </defs>
      <rect width={1400} height={2300} fill="url(#zphex)" />
    </svg>
    <AbsoluteFill style={{ background: `radial-gradient(70% 45% at 50% 46%, rgba(${tint},0.14) 0%, rgba(${tint},0) 70%)` }} />
    {rays > 0 ? (
      <svg width={2200} height={2200} viewBox="-1100 -1100 2200 2200" style={{ position: "absolute", left: 540 - 1100, top: 900 - 1100, opacity: rays, transform: `rotate(${(t * 22).toFixed(1)}deg)` }}>
        {Array.from({ length: 18 }, (_, i) => (
          <path key={i} d="M0 0 L-40 -1080 L40 -1080 Z" fill={LIME} opacity={i % 2 ? 0.4 : 0.18} transform={`rotate(${i * 20})`} />
        ))}
      </svg>
    ) : null}
    {[0, 1, 2].map((i) => {
      const u = ((t * 0.5 + i * 0.37) % 1) * 2 - 0.5;
      return <div key={i} style={{ position: "absolute", left: -400 + u * 1500, top: 300 + i * 560, width: 520, height: 5, background: `linear-gradient(90deg, rgba(${tint},0) 0%, rgba(${tint},0.75) 60%, rgba(255,255,255,0.8) 100%)`, transform: "rotate(-24deg)", borderRadius: 3 }} />;
    })}
    {Array.from({ length: 24 }, (_, i) => {
      const s = 6 + ((i * 37) % 4) * 4;
      const y = 2000 - ((t * (60 + ((i * 53) % 8) * 24) + i * 311) % 2100);
      const x = ((i * 197) % 1080) + Math.sin(t * 0.8 + i) * 30;
      return <div key={i} style={{ position: "absolute", left: x, top: y, width: s, height: s, borderRadius: 2, background: i % 5 === 0 ? WHITE : `rgb(${tint})`, opacity: 0.14 + ((i * 29) % 7) / 30, transform: `rotate(${(45 + t * 40 + i * 30).toFixed(0)}deg)` }} />;
    })}
    <AbsoluteFill style={{ background: "radial-gradient(95% 75% at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.62) 100%)" }} />
  </AbsoluteFill>
);
const Blade: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  if (t < at - 0.32 || t > at + 0.36) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 30 }}>
      {[LIME, "#000000"].map((c, i) => {
        const p = interpolate(t, [at - 0.3 + i * 0.06, at + 0.24 + i * 0.06], [0, 1], { ...cl, easing: IN_OUT });
        return <div key={i} style={{ position: "absolute", left: -2400 + p * 4600, top: -300, width: 1700, height: 2600, background: c, transform: "skewX(-18deg)" }} />;
      })}
    </AbsoluteFill>
  );
};
const Stage: React.FC<{ children: React.ReactNode; origin?: string; depth?: number }> = ({ children, origin = "50% 50%", depth = 1400 }) => (
  <AbsoluteFill style={{ perspective: depth, perspectiveOrigin: origin }}>{children}</AbsoluteFill>
);

// ───────── texto cinético em Orbitron ─────────
type W = [string, number, string?];
const K: React.FC<{ t: number; words: W[]; size: number; color?: string; weight?: number }> = ({ t, words, size, color = WHITE, weight = 900 }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: size * 0.32, whiteSpace: "nowrap", fontFamily: ORB, fontWeight: weight, fontSize: size, lineHeight: 1.12, letterSpacing: "0.01em", textTransform: "uppercase", color }}>
    {words.map(([w, at, c], i) => {
      const e = k(t, v(at) - 0.04, 0.24);
      const col = c ?? color;
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, v(at) - 0.04, 0.07), transform: `scale(${(1 + (1 - e) * 0.7).toFixed(3)}) translateY(${((1 - e) * size * 0.2).toFixed(1)}px)`, color: col, textShadow: col === WHITE ? "0 5px 0 rgba(0,0,0,0.6)" : `${glow(col === LIME ? GREEN : col, 0.9)}, 0 5px 0 rgba(0,0,0,0.6)` }}>{w}</span>
      );
    })}
  </div>
);
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);
// logo.png e z.png já estão recortados do fundo preto (alfa pela luminância)
const Logo: React.FC<{ w: number; style?: React.CSSProperties; z?: boolean }> = ({ w, style, z }) => <Img src={asset(z ? "z.png" : "logo.png")} style={{ width: w, display: "block", ...style }} />;

// ───────── cena 1: pagar caro em streaming — as assinaturas se empilham e o total do mês estoura ─────────
const APPS: { name: string; bg: string; fg: string }[] = [
  { name: "NETFLIX", bg: "#0B0B0B", fg: "#E50914" },
  { name: "HBO", bg: "linear-gradient(135deg, #6A2BE2 0%, #2A0A6B 100%)", fg: "#FFFFFF" },
  { name: "Paramount+", bg: "linear-gradient(135deg, #0A6BFF 0%, #0038B8 100%)", fg: "#FFFFFF" },
  { name: "Disney+", bg: "linear-gradient(135deg, #142B6F 0%, #0A1538 100%)", fg: "#FFFFFF" },
  { name: "prime video", bg: "linear-gradient(135deg, #12324A 0%, #0A1C2B 100%)", fg: "#33B6FF" },
];
const P1: [number, number, number][] = [[100, 800, -5], [580, 800, 5], [340, 1090, -2], [570, 920, 0], [340, 1190, 0]];
const P2: [number, number, number][] = [[110, 650, -3], [570, 650, 3], [110, 920, 2], [570, 920, -2], [340, 1190, 0]];
const BORN = [v(1.13), v(1.13) + 0.13, v(1.13) + 0.26, v(2.29) + 0.05, v(2.75) + 0.05];
const Pain: React.FC<{ t: number }> = ({ t }) => {
  const re = io(t, 1.78, 0.5);
  const b = v(3.67) - 0.12;
  const two = t >= b;
  const [sx, sy] = shakeOf(t, v(0.15) - 0.1, 14);
  const [mx, my] = shakeOf(t, v(4.11), 12, 0.4);
  const fill = lin(t, b + 0.1, v(4.87) + 0.2);
  return (
    <>
      <Back t={t} tint={two ? "255,59,59" : "89,214,0"} />
      {t < 0.5 ? <AbsoluteFill style={{ background: RED, opacity: 0.35 * (1 - k(t, 0, 0.5)) }} /> : null}
      {/* notas indo embora */}
      {Array.from({ length: 12 }, (_, i) => {
        const u = ((t * (0.5 + (i % 4) * 0.12) + i * 0.21) % 1);
        return (
          <div key={i} style={{ position: "absolute", left: 60 + ((i * 173) % 900) + Math.sin(t * 2 + i) * 40, top: 1900 - u * 2100, width: 170, height: 86, borderRadius: 10, background: "#1E7A3C", border: "4px solid #49C06E", boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: EXO, fontWeight: 900, fontSize: 42, color: "#B9F5CB", opacity: 0.6, transform: `rotate(${(Math.sin(t * 3 + i * 2) * 28).toFixed(1)}deg) scale(${0.7 + (i % 3) * 0.2})` }}>R$</div>
        );
      })}
      <Stage depth={1300} origin="50% 55%">
        <div style={{ position: "absolute", inset: 0, transformStyle: "preserve-3d", transform: `translate3d(${(sx + mx).toFixed(1)}px, ${(sy + my).toFixed(1)}px, ${(lin(t, 0, 5.8) * 70).toFixed(1)}px) rotateY(${mix(-9, 8, lin(t, 0, 5.8)).toFixed(2)}deg) rotateX(5deg)` }}>
          {APPS.map((a, i) => {
            if (t < BORN[i]) return null;
            const e = pop(t, BORN[i], 0.4);
            const x = mix(P1[i][0], P2[i][0], re);
            const y = mix(P1[i][1], P2[i][1], re);
            const r = mix(P1[i][2], P2[i][2], re);
            const charge = two ? pop(t, b + 0.1 + i * 0.12, 0.3) : 0;
            return (
              <div key={a.name} style={{ position: "absolute", left: x, top: y, width: 400, height: 236, borderRadius: 34, background: a.bg, border: "3px solid rgba(255,255,255,0.2)", boxSizing: "border-box", boxShadow: "0 30px 60px rgba(0,0,0,0.7)", transform: `translateZ(${(1 - e) * 500}px) rotate(${r}deg) scale(${(e * (1 + bump(t, b + 0.1 + i * 0.12, 0.08))).toFixed(3)})`, opacity: Math.min(1, e * 3), display: "flex", alignItems: "center", justifyContent: "center" }}>
                <div style={{ fontFamily: EXO, fontWeight: 900, fontSize: a.name.length <= 3 ? 112 : a.name.length <= 7 ? 74 : 56, color: a.fg, letterSpacing: a.name === "NETFLIX" ? "0.04em" : "-0.01em", marginTop: -24 }}>{a.name}</div>
                <div style={{ position: "absolute", left: 22, bottom: 16, fontFamily: EXO, fontWeight: 600, fontSize: 22, color: "rgba(255,255,255,0.7)", letterSpacing: "0.08em" }}>ASSINATURA MENSAL</div>
                <div style={{ position: "absolute", right: -16, top: -22, fontFamily: EXO, fontWeight: 900, fontSize: 40, color: WHITE, background: RED, borderRadius: 16, padding: "2px 16px", transform: `rotate(8deg) scale(${charge.toFixed(3)})`, boxShadow: glow(RED, 0.6) }}>− R$</div>
              </div>
            );
          })}
        </div>
      </Stage>
      {/* o total do mês estourando */}
      {two ? (
        <div style={{ position: "absolute", left: 110, top: 1490, width: 860, opacity: k(t, b, 0.2), transform: `translate(${mx.toFixed(1)}px, ${my.toFixed(1)}px)` }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: EXO, fontWeight: 800, fontSize: 38, color: WHITE, letterSpacing: "0.06em" }}>
            <span>TOTAL DO MÊS</span>
            <span style={{ color: RED }}>{"R$ " + "$".repeat(1 + Math.floor(fill * 3.99))}</span>
          </div>
          <div style={{ marginTop: 12, height: 44, borderRadius: 22, background: "#1E1E1E", border: `3px solid ${EDGE}`, overflow: "hidden", boxSizing: "border-box" }}>
            <div style={{ width: `${(fill * 100).toFixed(1)}%`, height: "100%", background: `linear-gradient(90deg, #FF9A3B 0%, ${RED} 70%)`, boxShadow: glow(RED, 0.6) }} />
          </div>
        </div>
      ) : null}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, #050505 0%, rgba(5,5,5,0.9) 26%, rgba(5,5,5,0) 36%)" }} />
      {t < 1.78 ? (
        <Col top={260} gap={4} style={{ transform: `translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px)` }}>
          <K t={t} size={112} words={[["Chega", -0.6], ["de", 0.35]]} />
          <K t={t} size={100} color={RED} words={[["pagar", 0.45], ["caro", 0.79]]} />
          <K t={t} size={80} words={[["em", 0.99], ["streaming!", 1.13]]} />
        </Col>
      ) : !two ? (
        <Col top={250} gap={4}>
          <K t={t} size={92} words={[["Cansado", 1.67], ["de", 2.21]]} />
          <K t={t} size={70} words={[["assinar", 2.29], ["vários", 2.75]]} />
          <K t={t} size={92} color={RED} words={[["aplicativos", 3.05]]} />
        </Col>
      ) : (
        <Col top={250} gap={4}>
          <K t={t} size={92} words={[["e", 3.61], ["gastar", 3.67]]} />
          <K t={t} size={88} color={RED} words={[["uma", 3.95], ["fortuna", 4.11]]} />
          <K t={t} size={92} words={[["todo", 4.67], ["mês?", 4.87]]} />
        </Col>
      )}
    </>
  );
};

// ───────── cena 2: Zone Play — a grade enche, uma categoria por vez; "tudo em um só lugar" ─────────
const ICONS: React.ReactNode[] = [
  <g key="f"><rect x={14} y={38} width={72} height={46} rx={6} /><path d="M14 38 L20 20 L88 30 L86 38" /><path d="M32 22 L40 37 M50 25 L58 37 M68 27 L76 37" /><path d="M42 52 L62 62 L42 72 Z" fill="currentColor" /></g>,
  <g key="s"><rect x={10} y={30} width={62} height={44} rx={6} /><path d="M24 22 H84 a6 6 0 0 1 6 6 V62" /><path d="M34 44 L52 52 L34 60 Z" fill="currentColor" /><path d="M28 84 H56" /></g>,
  <g key="l"><path d="M50 46 V88 M36 88 H64 M50 46 L34 88 M50 46 L66 88" /><circle cx={50} cy={40} r={6} fill="currentColor" /><path d="M34 28 a22 22 0 0 0 0 26 M66 28 a22 22 0 0 1 0 26 M24 18 a36 36 0 0 0 0 44 M76 18 a36 36 0 0 1 0 44" /></g>,
  <g key="e"><circle cx={50} cy={52} r={34} /><path d="M50 38 L63 47 L58 62 H42 L37 47 Z" fill="currentColor" /><path d="M50 38 V20 M63 47 L80 40 M58 62 L68 78 M42 62 L32 78 M37 47 L20 40" /></g>,
  <g key="k"><circle cx={50} cy={56} r={26} /><circle cx={28} cy={30} r={11} /><circle cx={72} cy={30} r={11} /><circle cx={41} cy={52} r={3.5} fill="currentColor" /><circle cx={59} cy={52} r={3.5} fill="currentColor" /><path d="M42 64 q8 7 16 0" /></g>,
];
const CATS = ["FILMES", "SÉRIES", "AO VIVO", "ESPORTES", "INFANTIL"];
const CAT_AT = [v(6.81), v(7.49), v(8.01), v(8.95), v(9.65)];
const TILE: [number, number][] = [[50, 420], [560, 420], [50, 850], [560, 850], [50, 1280], [560, 1280]];
const CAM: [number, number, number, number][] = [
  [5.6, 1.8, 540, 330],
  [6.78, 1.5, 285, 620],
  [7.46, 1.5, 795, 620],
  [7.98, 1.5, 285, 1050],
  [8.92, 1.5, 795, 1050],
  [9.62, 1.5, 285, 1480],
  [10.75, 0.8, 540, 1010],
];
const Have: React.FC<{ t: number }> = ({ t }) => {
  const a = 5.8;
  const hit = v(5.95) - 0.05;
  let s = CAM[0][1];
  let cx = CAM[0][2];
  let cy = CAM[0][3];
  for (let i = 1; i < CAM.length; i++) {
    const p = io(t, CAM[i][0], 0.36);
    s += (CAM[i][1] - CAM[i - 1][1]) * p;
    cx += (CAM[i][2] - CAM[i - 1][2]) * p;
    cy += (CAM[i][3] - CAM[i - 1][3]) * p;
  }
  s *= 1 + Math.sin(t * 2.1) * 0.012 + CAT_AT.reduce((n, at) => n + bump(t, at, 0.05), 0) + bump(t, hit, 0.08);
  const all = t >= v(10.89) - 0.1;
  return (
    <>
      <Back t={t} rays={0.16 * (1 - io(t, 6.6, 0.4)) + (all ? 0.12 : 0)} />
      {[0, 0.12].map((dl) => {
        const u = k(t, hit + dl, 0.8);
        return u > 0 && u < 1 ? <div key={dl} style={{ position: "absolute", left: 540 - 380, top: 760 - 380, width: 760, height: 760, borderRadius: 380, border: `${(16 * (1 - u)).toFixed(1)}px solid ${LIME}`, boxSizing: "border-box", transform: `scale(${(0.3 + u * 2.2).toFixed(3)})`, opacity: 1 - u }} /> : null;
      })}
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 2000, transformOrigin: "0 0", transform: `translate(540px, 960px) scale(${s.toFixed(4)}) translate(${(-cx).toFixed(1)}px, ${(-cy).toFixed(1)}px) rotate(${(Math.sin(t * 1.3) * 0.8).toFixed(2)}deg)` }}>
        <Logo w={330} style={{ position: "absolute", left: 375, top: 30, transform: `scale(${(0.2 + 0.8 * k(t, hit, 0.35)).toFixed(3)}) rotate(${((1 - k(t, hit, 0.5)) * -20).toFixed(1)}deg)`, opacity: k(t, hit, 0.08), filter: "drop-shadow(0 0 16px rgba(120,230,0,0.45))" }} />
        {TILE.map(([x, y], i) => {
          const at = i < 5 ? CAT_AT[i] - 0.05 : v(10.89) + 0.25;
          const born = t >= at;
          const e = pop(t, at, 0.4);
          const hot = t < at + 0.9;
          return (
            <div key={i} style={{ position: "absolute", left: x, top: y, width: 470, height: 400 }}>
              <div style={{ position: "absolute", inset: 0, borderRadius: 34, border: "4px dashed rgba(198,255,26,0.4)", opacity: born || t < 6.6 ? 0 : 0.55 + 0.35 * Math.sin(t * 6 + i) }} />
              {born ? (
                <div style={{ position: "absolute", inset: 0, borderRadius: 34, background: i === 5 ? `linear-gradient(160deg, ${LIME} 0%, ${GREEN} 100%)` : `linear-gradient(160deg, #1A1F12 0%, ${PANEL} 100%)`, border: `4px solid ${hot || all ? LIME : EDGE}`, boxShadow: hot ? glow(GREEN, 0.9) : "0 20px 50px rgba(0,0,0,0.6)", boxSizing: "border-box", transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * -8).toFixed(2)}deg)`, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10 }}>
                  {i < 5 ? (
                    <>
                      <svg width={210} height={210} viewBox="0 0 100 100" fill="none" stroke={LIME} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" color={LIME} style={{ filter: `drop-shadow(0 0 8px ${GREEN})`, transform: `translateY(${(Math.sin(t * 3 + i) * 6).toFixed(1)}px)` }}>
                        {ICONS[i]}
                      </svg>
                      <div style={{ display: "flex", alignItems: "center", gap: 14, fontFamily: ORB, fontWeight: 900, fontSize: 50, color: WHITE, whiteSpace: "nowrap" }}>
                        {i === 2 ? <span style={{ width: 24, height: 24, borderRadius: 12, background: RED, opacity: Math.sin(t * 9) > 0 ? 1 : 0.3, boxShadow: glow(RED, 0.6) }} /> : null}
                        {CATS[i]}
                      </div>
                      {i === 2 ? <div style={{ fontFamily: EXO, fontWeight: 800, fontSize: 28, color: LIME, letterSpacing: "0.08em", marginTop: -6 }}>CANAIS DE TV</div> : null}
                    </>
                  ) : (
                    <div style={{ fontFamily: ORB, fontWeight: 900, fontSize: 58, lineHeight: 1.1, color: "#000", textAlign: "center" }}>
                      E MUITO
                      <br />
                      MAIS
                    </div>
                  )}
                </div>
              ) : null}
            </div>
          );
        })}
        <Col top={1730}>
          <K t={t} size={84} words={[["tudo", 10.89], ["em", 11.36]]} />
          <K t={t} size={104} color={LIME} words={[["um", 11.49], ["só", 11.63], ["lugar", 11.76]]} />
        </Col>
      </div>
      {t < 6.95 ? (
        <>
          <Col top={270} style={{ opacity: 1 - lin(t, 6.65, 6.85) }}>
            <K t={t} size={84} words={[["Com", 5.75], ["a", 5.87]]} />
          </Col>
          <Col top={1180} style={{ opacity: 1 - lin(t, 6.65, 6.85) }}>
            <K t={t} size={96} color={LIME} words={[["você", 6.37], ["tem", 6.57]]} />
          </Col>
        </>
      ) : null}
      <div style={{ display: "none" }}>{a}</div>
    </>
  );
};

// ───────── cena 3: o preço ─────────
const Price: React.FC<{ t: number }> = ({ t }) => {
  const a = 12.4;
  const hit = 13.18;
  const e = k(t, hit, 0.3);
  const [sx, sy] = shakeOf(t, hit, 18, 0.45);
